from __future__ import annotations

import argparse
import json
import re
from dataclasses import dataclass
from pathlib import Path

TEXT_EXTENSIONS = {".php", ".inc", ".phtml", ".html", ".htm", ".js", ".ts", ".py", ".sql"}
EXCLUDED_DIRS = {
    ".git", ".hermclaw", "model_runtime", "agent_core", "docs",
    "android_app", "node_modules", "vendor", ".venv", "venv",
    "__pycache__", "dist", "build"
}


@dataclass(frozen=True)
class Pattern:
    label: str
    regex: str
    weight: int


PATTERNS = [
    Pattern("benutzer_array_def", r"\bfunction\s+benutzer_array\s*\(", 60),
    Pattern("benutzer_array", r"\bbenutzer_array\s*\(", 22),
    Pattern("benutzer_liste", r"\bbenutzer_liste\b", 18),
    Pattern("GET_suche", r"\$_GET\s*\[\s*['\"]suche['\"]\s*\]", 22),
    Pattern("POST_suche", r"\$_POST\s*\[\s*['\"]suche['\"]\s*\]", 16),
    Pattern("input_suche", r"\bname\s*=\s*['\"]suche['\"]", 18),
    Pattern("suche", r"\bsuche\b", 3),
    Pattern("filter", r"\bfilter\w*\b", 2),
    Pattern("status", r"\bstatus\w*\b", 1),
    Pattern("empty_state", r"(Noch keine Benutzer|Keine Benutzer|keine Treffer|tabelle__leer)", 8),
    Pattern("rechte", r"(rechte_pruefen|berechtigung|berechtigungen)", 1),
]

USER_SYMBOLS = {"benutzer_array_def", "benutzer_array", "benutzer_liste"}
SEARCH_SYMBOLS = {"GET_suche", "POST_suche", "input_suche"}


def excluded(path: Path, root: Path) -> bool:
    rel = path.relative_to(root)
    return any(part in EXCLUDED_DIRS for part in rel.parts[:-1])


def _eligibility(rel: str, counts: dict[str, int]) -> tuple[bool, str]:
    lower = rel.lower()
    user_named = "benutzer" in lower or "/user" in lower or lower.startswith("user")
    has_user_symbol = any(name in counts for name in USER_SYMBOLS)
    has_search_symbol = any(name in counts for name in SEARCH_SYMBOLS)

    if user_named and has_user_symbol:
        return True, "Benutzer-bezogener Pfad mit direktem Benutzersymbol."
    if has_user_symbol and has_search_symbol:
        return True, "Benutzersymbol und konkreter Suchparameter im selben Codepfad."
    return False, "Nur generische, namensbasierte oder fachfremde Treffer."


def discover(root: Path) -> dict:
    candidates = []
    scanned = 0

    for path in root.rglob("*"):
        if not path.is_file() or excluded(path, root) or path.suffix.lower() not in TEXT_EXTENSIONS:
            continue
        try:
            if path.stat().st_size > 2_000_000:
                continue
        except OSError:
            continue

        scanned += 1
        rel = path.relative_to(root).as_posix()
        text = path.read_text(encoding="utf-8", errors="replace")
        lower_rel = rel.lower()

        score = 0
        if "benutzer" in lower_rel:
            score += 35
        elif "/user" in lower_rel or lower_rel.startswith("user"):
            score += 12

        if rel.startswith("nav/"):
            score += 5
        elif rel.startswith("inc/"):
            score += 8
        elif rel.startswith("api/"):
            score += 1

        counts = {}
        snippets = []
        lines = text.splitlines()

        for pattern in PATTERNS:
            matches = list(
                re.finditer(
                    pattern.regex,
                    text,
                    flags=re.IGNORECASE | re.MULTILINE,
                )
            )
            if not matches:
                continue

            counts[pattern.label] = len(matches)
            score += pattern.weight * min(len(matches), 6)

            for match in matches[:2]:
                line_no = text.count("\n", 0, match.start()) + 1
                start = max(0, line_no - 2)
                end = min(len(lines), line_no + 1)
                snippet = "\n".join(
                    f"{i + 1}: {lines[i][:240]}"
                    for i in range(start, end)
                )
                snippets.append(
                    {
                        "label": pattern.label,
                        "line": line_no,
                        "snippet": snippet,
                    }
                )

        if score <= 0:
            continue

        eligible, reason = _eligibility(rel, counts)
        candidates.append(
            {
                "path": rel,
                "score": score,
                "handoff_eligible": eligible,
                "eligibility_reason": reason,
                "pattern_counts": counts,
                "snippets": snippets[:10],
            }
        )

    candidates.sort(
        key=lambda item: (
            not item["handoff_eligible"],
            -item["score"],
            item["path"],
        )
    )

    eligible_count = sum(
        1 for item in candidates if item["handoff_eligible"]
    )
    return {
        "schema": 3,
        "profile": "benutzerfilter",
        "scanned_files": scanned,
        "eligible_count": eligible_count,
        "candidate_count": min(12, len(candidates)),
        "candidates": candidates[:12],
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    root = Path(args.root).resolve()
    result = discover(root)

    output = Path(args.output)
    output.write_text(
        json.dumps(result, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    print(f"[DISCOVERY] {result['scanned_files']} Dateien geprüft.")
    print(
        f"[DISCOVERY] {result['eligible_count']} Kandidat(en) "
        "für Handoff zugelassen."
    )

    for idx, item in enumerate(result["candidates"], start=1):
        labels = ", ".join(item["pattern_counts"].keys()) or "nur Dateiname"
        marker = "ELIGIBLE" if item["handoff_eligible"] else "IGNORED"
        print(
            f"[DISCOVERY] {idx}. [{marker}] {item['path']} | "
            f"score={item['score']} | {labels}"
        )

    print(f"[DISCOVERY] Ergebnis: {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import argparse
import json
from pathlib import Path


def render(handoff: dict) -> str:
    paths = handoff.get("target_paths") or []
    if handoff.get("target_role") != "main" or not paths:
        raise ValueError("Ungültiges oder leeres Main-Handoff.")
    if len(paths) > 5:
        raise ValueError(
            "Main-Handoff enthält mehr als 5 target_paths."
        )

    findings = "\n".join(
        f"- {item.get('path')}: "
        f"{item.get('symbol', '')} — "
        f"{item.get('evidence', '')}"
        for item in handoff.get("findings", [])
    )
    requested = "\n".join(
        f"- {item}"
        for item in handoff.get("requested_changes", [])
    )
    constraints = "\n".join(
        f"- {item}"
        for item in handoff.get("constraints", [])
    )
    tests = "\n".join(
        f"- {item}"
        for item in handoff.get("tests", [])
    )
    forbidden = "\n".join(
        f"- {item}"
        for item in handoff.get("forbidden_paths", [])
    ) or "- keine"
    path_list = "\n".join(
        f"- {path}" for path in paths
    )

    return f"""MAIN-CODER-AUFTRAG – gezielte Implementierung aus validiertem Discovery-Handoff

ZIEL:
{handoff.get("task", "")}

ACCEPTANCE-PROFIL:
{handoff.get("acceptance_profile", "generic")}

VERBINDLICHE ZIELDATEIEN:
{path_list}

BEFUNDE AUS DER DETERMINISTISCHEN DISCOVERY:
{findings}

UMZUSETZEN:
{requested}

CONSTRAINTS:
{constraints}

VERBOTENE / FACHFREMDE PFADE:
{forbidden}

PRÜFUNGEN:
{tests}

ARBEITSREGELN:
- Beginne direkt mit den angegebenen target_paths.
- Keine breite Repository-Suche und kein Wiki-Exploring.
- Verbotene/fachfremde Pfade nicht ändern.
- Keine globale Validierungsfunktion ändern, sofern sie nicht in target_paths steht und zwingend erforderlich ist.
- Wenn ein direkter technischer Abhängigkeitspfad gelesen werden muss, begründe ihn kurz; ändere ihn nur, wenn es für die Aufgabe zwingend ist.
- Bestehende Berechtigungs- und Statuslogik erhalten.
- Implementiere ALLE Punkte aus UMZUSETZEN, nicht nur eine Teilmenge.
- Führe die angegebenen Tests/Syntaxchecks aus und prüfe anschließend den Diff.
- Wenn die Anforderungen mit den angegebenen Dateien nicht sicher umsetzbar sind, nicht raten: mit klarer Blockade/Begründung beenden.
- Keine fachlich fremden Refactorings.

ABSCHLUSS:
- Bei Erfolg normale finish-Aktion mit Zusammenfassung, Tests und geänderten Dateien.
- Der Auftrag ist erst abgeschlossen, wenn die tatsächliche Implementierung und die möglichen lokalen Prüfungen erfolgt sind.
"""


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--handoff", required=True)
    args = parser.parse_args()
    handoff = json.loads(
        Path(args.handoff).read_text(encoding="utf-8")
    )
    print(render(handoff))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import tempfile
import unittest
from pathlib import Path

from model_runtime.deterministic_discovery import discover
from model_runtime.fast_handoff import canonicalize
from model_runtime.main_task import render


class PipelineContractTests(unittest.TestCase):
    def test_mcp_user_page_is_not_handoff_eligible_without_user_symbol(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "nav").mkdir()
            (root / "inc").mkdir()
            (root / "nav" / "settings_mcp_benutzer.php").write_text(
                "<?php echo 'Keine Benutzer'; rechte_pruefen('x');",
                encoding="utf-8",
            )
            (root / "nav" / "settings_benutzer.php").write_text(
                "<?php $benutzer_liste = benutzer_array();",
                encoding="utf-8",
            )
            (root / "inc" / "funktionen_benutzer.php").write_text(
                "<?php function benutzer_array() { return []; }",
                encoding="utf-8",
            )

            result = discover(root)
            by_path = {
                item["path"]: item
                for item in result["candidates"]
            }

            self.assertFalse(
                by_path[
                    "nav/settings_mcp_benutzer.php"
                ]["handoff_eligible"]
            )
            self.assertTrue(
                by_path[
                    "nav/settings_benutzer.php"
                ]["handoff_eligible"]
            )

    def test_canonicalize_restores_mandatory_acceptance_requirements(self):
        result = canonicalize(
            {
                "requested_changes": ["nur ein Modellpunkt"],
                "constraints": [],
                "tests": [],
                "forbidden_paths": [],
            }
        )
        self.assertEqual(
            result["acceptance_profile"],
            "benutzerfilter-v1",
        )
        self.assertTrue(
            any(
                "normalisierten Suchwert" in item
                for item in result["requested_changes"]
            )
        )
        self.assertTrue(
            any(
                "Nicht-skalare" in item
                for item in result["requested_changes"]
            )
        )
        self.assertIn(
            "nav/work_agents.php",
            result["forbidden_paths"],
        )

    def test_main_task_includes_forbidden_paths(self):
        task = render(
            {
                "target_role": "main",
                "target_paths": ["nav/settings_benutzer.php"],
                "forbidden_paths": ["wiki.php"],
                "acceptance_profile": "benutzerfilter-v1",
            }
        )
        self.assertIn("wiki.php", task)
        self.assertIn("benutzerfilter-v1", task)


if __name__ == "__main__":
    unittest.main()
